// Reuse the material already read for this exact file. This keeps quiz and
// flashcard generation from reading a large PDF/PPTX again after a summary.
function studyFileIdentity(file){return file?[String(file.name||''),String(file.size||0),String(file.lastModified||0)].join('|'):''}
function studyTextDataUrl(text){return `data:text/plain;base64,${btoa(unescape(encodeURIComponent(String(text||''))))}`}
const studyflowBaseRenderStudyResult=renderStudyResult;
renderStudyResult=function(data,footer){if(data?.action==='summary'&&window.studyflowPendingStudyIdentity){if(data.sourceText){window.studyflowLastStudyMaterial={identity:window.studyflowPendingStudyIdentity,name:data.sourceName||window.studyflowPendingStudyName||'เนื้อหาที่อ่านไว้',content:String(data.sourceText),digest:String(data.sourceDigest||'')}}else window.studyflowLastStudyMaterial=null;window.studyflowPendingStudyIdentity='';window.studyflowPendingStudyName=''}return studyflowBaseRenderStudyResult(data,footer)};
const studyflowBaseGenerateFileStudy=generateFileStudy;
generateFileStudy=async function(action='summary'){const file=document.querySelector('#study-file-input')?.files?.[0],identity=studyFileIdentity(file),previous=window.studyflowLastStudyMaterial;if(action==='summary'&&file){window.studyflowPendingStudyIdentity=identity;window.studyflowPendingStudyName=file.name}if(action==='summary'||!file||!previous||previous.identity!==identity)return studyflowBaseGenerateFileStudy(action);if(file.size>50*1024*1024){showToast('ไฟล์ต้องมีขนาดไม่เกิน 50 MB');return}const settings=await openStudyConfigModal(action);if(!settings)return;const progressId=`study-reuse-${Date.now()}-${Math.random().toString(36).slice(2)}`;setStudyLoading(`กำลัง${action==='quiz'?'สร้างข้อสอบ':'สร้างแฟลชการ์ด'}จากเนื้อหาที่อ่านแล้ว...`,'ไม่ต้องอ่านหรืออัปโหลดไฟล์ซ้ำ');const stopProgress=watchStudyProgress(progressId);try{const virtualFile={name:`${previous.name} · เนื้อหาที่อ่านแล้ว.txt`,mimeType:'text/plain',size:previous.content.length,data:studyTextDataUrl(previous.content)};window.studyflowLastStudyFile=virtualFile;const data=await uploadStudyFileWithProgress({progressId,action,studySettings:settings,file:virtualFile});updateStudyProgress(100,'ประมวลผลเสร็จแล้ว','กำลังแสดงผลลัพธ์…');renderStudyResult(data,`อ้างอิงจากเนื้อหาที่อ่านไว้แล้ว · ${previous.name}`)}catch(error){renderStudyResult({source:'fallback',action,title:previous.name,content:error.message||'ประมวลผลไม่สำเร็จ'},`อ้างอิงจากเนื้อหาที่อ่านไว้แล้ว · ${previous.name}`)}finally{stopProgress()}};

const calendarPlannerMarkup=`<div class="planner-heading"><div><span class="eyebrow">SMART TIME PLANNER</span><h2>ปฏิทินของฉัน</h2><p>แยกดูวันส่งงาน เวลาติว และช่วงลงมือทำงาน เพื่อไม่ให้งานถมกัน</p></div><div class="planner-date"><button aria-label="ช่วงก่อนหน้า">‹</button><strong>สัปดาห์นี้</strong><button aria-label="ช่วงถัดไป">›</button><div class="calendar-view-toggle" role="group" aria-label="มุมมองปฏิทิน"><button class="active" type="button" data-calendar-view="week">สัปดาห์</button><button type="button" data-calendar-view="month">เดือน</button></div></div></div><div class="calendar-switcher"><button class="calendar-tab active" data-calendar="deadline">◷ วันส่งงาน <span>5</span><small>กำหนดส่งจริง</small></button><button class="calendar-tab" data-calendar="study">✺ ปฏิทินการติว <span>6</span><small>เวลาทบทวน</small></button><button class="calendar-tab" data-calendar="work">▦ ปฏิทินการทำงาน <span>8</span><small>แบ่งงานย่อย</small></button></div><div class="planner-summary"><div><span class="summary-dot deadline-dot"></span><strong id="calendar-mode-title">งานที่ต้องส่ง</strong><small id="calendar-mode-subtitle">กำหนดส่งจาก Google Classroom</small></div><div class="load-meter"><span>ภาระงานสัปดาห์นี้</span><b>68%</b><i><em></em></i></div></div><div class="three-calendar" id="three-calendar"></div>`;
const calendarModes={deadline:{title:'งานที่ต้องส่ง',subtitle:'กำหนดส่งจาก Google Classroom',dot:'deadline-dot',events:[['พฤหัสบดี 14','แบบฝึกหัด Unit 4','ภาษาอังกฤษ','deadline-event'],['เสาร์ 16','ร่างโครงงานมายแมพ','ชีววิทยา','deadline-event'],['จันทร์ 18','ส่งรายงานกลุ่ม','ภาษาไทย','deadline-event']]},study:{title:'เวลาติว',subtitle:'ช่วงทบทวนที่ AI จัดให้ตามเวลาว่าง',dot:'study-dot',events:[['พฤหัสบดี 14','ติว: ระบบหายใจ','ชีววิทยา','study-event'],['ศุกร์ 15','ติว: Unit 4','ภาษาอังกฤษ','study-event'],['อาทิตย์ 17','ทบทวนฟิสิกส์','ฟิสิกส์','study-event']]},work:{title:'ช่วงลงมือทำงาน',subtitle:'งานย่อยที่กระจายเพื่อไม่ให้ทำงานหนักวันเดียว',dot:'work-dot',events:[['พฤหัสบดี 14','อ่านเนื้อหา · 25 นาที','มายแมพชีวะ','work-event'],['ศุกร์ 15','ออกแบบตกแต่ง · 40 นาที','มายแมพชีวะ','work-event'],['เสาร์ 16','ตรวจงาน · 20 นาที','มายแมพชีวะ','work-event'],['จันทร์ 18','ร่างรายงาน · 30 นาที','ภาษาไทย','work-event']]}};
