const escapeTaskHtml=value=>String(value||'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[character]));
function renderThreeCalendarLegacy(mode='deadline'){const data=calendarModes[mode],wrap=document.querySelector('#three-calendar');if(!wrap)return;document.querySelector('#calendar-mode-title').textContent=data.title;document.querySelector('#calendar-mode-subtitle').textContent=data.subtitle;document.querySelector('.summary-dot').className=`summary-dot ${data.dot}`;const days=['จ. 11','อ. 12','พ. 13','พฤ. 14','ศ. 15','ส. 16','อา. 17'];wrap.innerHTML=days.map((d,i)=>{const event=data.events.find(e=>e[0].includes(d.split(' ')[1]));return`<div class="planner-day ${i===3?'current-day':''}"><span>${d}</span>${event?`<div class="planner-event ${event[3]}"><b>${event[1]}</b><small>${event[2]}</small></div>`:'<div class="empty-slot">ว่าง</div>'}</div>`}).join('')}
function renderCalendarPlanner(){const view=document.querySelector('#calendar-view');if(!view)return;view.innerHTML=calendarPlannerMarkup+plannerImpactMarkup+`<section class="planner-assistant"><div><span class="eyebrow">LIFE PLANNER AI</span><h3>เล่าเวลาในชีวิตประจำวันของคุณ</h3><p>เช่น เรียนจันทร์–ศุกร์ 08:00–16:00 นอน 23:00 ออกกำลังกายวันพุธ และมีเวลาว่างหลัง 18:00</p></div><textarea id="routine-input" placeholder="พิมพ์กิจวัตร เวลานอน เวลาเรียน และช่วงเวลาที่ไม่สะดวก..."></textarea><div class="planner-assistant-actions"><button class="primary-btn" id="generate-plan">✦ จัดแผนให้ฉัน</button><label><input type="checkbox" id="planner-ai-consent"> อนุญาตส่งข้อมูลนี้ให้ OpenAI เพื่อวิเคราะห์เชิงลึก</label></div><div id="planner-assistant-result" class="planner-assistant-result"><span>ยังไม่ได้สร้างแผน</span></div></section>`;document.querySelectorAll('.calendar-tab').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.calendar-tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');renderThreeCalendar(btn.dataset.calendar)});renderThreeCalendar();renderPlannerImpactMetrics();let savedChange=null;try{savedChange=JSON.parse(localStorage.getItem('studyflow.planChange')||'null')}catch{}renderPlanChangeNotice(savedChange);setupPlannerAssistant()}
