async function refreshClassroomTasks(){try{const response=await fetch('/api/classroom/tasks',{cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||'โหลดงานไม่สำเร็จ');const incoming=Array.isArray(data.tasks)?data.tasks:[];tasks.splice(0,tasks.length,...incoming);renderTasks();const total=tasks.length,done=tasks.filter(x=>x.done).length,active=total-done;document.querySelector('.nav-badge')?.replaceChildren(document.createTextNode(String(total)));document.querySelectorAll('.filter span')[0]?.replaceChildren(document.createTextNode(String(total)));document.querySelectorAll('.filter span')[1]?.replaceChildren(document.createTextNode(String(active)));document.querySelectorAll('.filter span')[2]?.replaceChildren(document.createTextNode(String(done)));document.querySelectorAll('.tab span')[0]?.replaceChildren(document.createTextNode(String(tasks.filter(x=>/วันนี้/.test(x.deadline||'')).length)));document.querySelectorAll('.tab span')[1]?.replaceChildren(document.createTextNode(String(tasks.filter(x=>/พรุ่งนี้/.test(x.deadline||'')).length)));document.querySelectorAll('.tab span')[2]?.replaceChildren(document.createTextNode(String(total)));const progress=document.querySelector('.big-number');if(progress)progress.innerHTML=total?`${Math.round(done/total*100)}<span>%</span>`:'—';const meta=document.querySelector('.progress-meta');if(meta)meta.innerHTML=`<span>ทำเสร็จแล้ว ${done} งาน</span><span>เหลืออีก ${active} งาน</span>`;const insight=document.querySelector('.insight-card p');if(insight)insight.textContent=total?'ระบบดึงงานจาก Google Classroom แล้ว คุณสามารถเปิดงานทั้งหมดเพื่อเริ่มจัดลำดับเวลาได้':'ยังไม่มีงานใน Google Classroom ขณะนี้';if(typeof syncTaskDeadlinesToCalendar==='function')syncTaskDeadlinesToCalendar();}catch(error){console.warn('Classroom task sync failed',error)}}
