function renderPlannerImpactMetrics(){const target=document.querySelector('#planner-impact-metrics');if(!target)return;const metrics=readPlannerMetrics(),pending=tasks.filter(task=>!task.done).length,done=tasks.filter(task=>task.done).length,sleep=Number(metrics.sleepProtectedMinutes||0);target.innerHTML=`<div class="planner-impact-heading"><div><span class="eyebrow">PLAN IMPACT</span><strong>ผลของแผนต่อการเรียนและการพักผ่อน</strong></div><small>${metrics.lastUpdated?'อัปเดตล่าสุด '+new Date(metrics.lastUpdated).toLocaleString('th-TH'):'รอข้อมูลจริงจากการจัดแผน'}</small></div><div class="planner-impact-grid"><article><b>${pending}</b><span>งานที่ยังค้าง</span></article><article><b>${done}</b><span>งานที่เสร็จแล้ว</span></article><article><b>${Number(metrics.reschedules||0)}</b><span>ครั้งที่ปรับแผน</span></article><article><b>${sleep?sleep+' นาที':'—'}</b><span>เวลานอนที่กันไว้</span></article><article><b>${Number(metrics.reviewBlocks||0)}</b><span>ช่วงทบทวนจากผลสอบ</span></article></div><p class="planner-impact-note">ตัวเลขนี้มาจากข้อมูลที่ผู้ใช้เชื่อมต่อและการกระทำในโปรแกรมเท่านั้น หากยังไม่จัดกิจวัตรหรือยังไม่มีงาน ระบบจะไม่คาดเดาตัวเลขแทน</p>`}
