function recordTaskPlanChange(beforeTasks,afterTasks){const beforeIds=new Set(beforeTasks.map(task=>String(task.id||task.courseWorkId||task.title))),added=afterTasks.filter(task=>!beforeIds.has(String(task.id||task.courseWorkId||task.title)));if(!beforeTasks.length||!added.length)return;const beforeEvents=(calendarModes.work.events||[]).slice(0,8).map(event=>`${event[0]} · ${event[1]}`),events=(calendarModes.work.events||[]).slice();added.slice(0,8).forEach((task,index)=>{const date=new Date();date.setDate(date.getDate()+Math.min(6,index+1));const key=typeof taskDeadlineKey==='function'&&taskDeadlineKey(task.deadline)||calendarDateKey(date);const title=`เริ่มงาน: ${task.title}`;if(!events.some(event=>String(event[1]||'')===title))events.push([key,title,task.tag||'งานจาก Classroom','work-event','30 นาที',`auto-${task.id||Date.now()}-${index}`,false,'งานใหม่เข้ามา จึงกันช่วงเริ่มต้น 30 นาทีและจัดก่อนเพื่อไม่ให้ไปกองใกล้กำหนดส่ง'])});calendarModes.work.events=events;const afterEvents=events.slice(0,8).map(event=>`${event[0]} · ${event[1]}`);const change={before:beforeEvents,after:afterEvents,reason:`พบงานใหม่ ${added.length} งาน จึงเพิ่มช่วงเริ่มต้นและกระจายออกจากวันเดียวกัน`,updatedAt:Date.now()};localStorage.setItem('studyflow.planChange',JSON.stringify(change));const metrics=readPlannerMetrics();metrics.reschedules=Number(metrics.reschedules||0)+1;metrics.lastUpdated=Date.now();localStorage.setItem('studyflow.planMetrics',JSON.stringify(metrics));renderPlanChangeNotice(change);renderPlannerImpactMetrics()}
var calendarWeekOffset=0,calendarMonthOffset=0,calendarViewMode='week';
function calendarDateKey(date){return date.toISOString().slice(0,10)}
function taskDeadlineKey(value){const m=(value||'').match(/(\d{1,2})\s+(ม\.ค\.|ก\.พ\.|มี\.ค\.|เม\.ย\.|พ\.ค\.|มิ\.ย\.|ก\.ค\.|ส\.ค\.|ก\.ย\.|ต\.ค\.|พ\.ย\.|ธ\.ค\.)\s+(\d{4})/);if(!m)return null;const months={'ม.ค.':0,'ก.พ.':1,'มี.ค.':2,'เม.ย.':3,'พ.ค.':4,'มิ.ย.':5,'ก.ค.':6,'ส.ค.':7,'ก.ย.':8,'ต.ค.':9,'พ.ย.':10,'ธ.ค.':11};return calendarDateKey(new Date(Number(m[3])-543,months[m[2]],Number(m[1])))}
function renderThreeCalendar(mode='deadline'){const data=calendarModes[mode],wrap=document.querySelector('#three-calendar');if(!wrap)return;const title=document.querySelector('.planner-date strong'),fmt=d=>`${d.getDate()} ${d.toLocaleDateString('th-TH',{month:'short'})}`;document.querySelector('#calendar-mode-title').textContent=data.title;document.querySelector('#calendar-mode-subtitle').textContent=data.subtitle;document.querySelector('.summary-dot').className=`summary-dot ${data.dot}`;document.querySelectorAll('[data-calendar-view]').forEach(btn=>btn.classList.toggle('active',btn.dataset.calendarView===calendarViewMode));if(calendarViewMode==='month'){const month=new Date();month.setDate(1);month.setMonth(month.getMonth()+calendarMonthOffset);const monthStart=new Date(month);monthStart.setDate(1-((month.getDay()+6)%7));const monthEnd=new Date(monthStart);monthEnd.setDate(monthStart.getDate()+41);if(title)title.textContent=month.toLocaleDateString('th-TH',{month:'long',year:'numeric'});const dayNames=['จ.','อ.','พ.','พฤ.','ศ.','ส.','อา.'];wrap.innerHTML=`<div class="month-weekdays">${dayNames.map(label=>`<span>${label}</span>`).join('')}</div><div class="month-grid">${Array.from({length:42},(_,i)=>{const d=new Date(monthStart);d.setDate(monthStart.getDate()+i);const key=calendarDateKey(d),dayEvents=data.events.filter(e=>e[0]===key);return`<div class="month-day ${d.getMonth()!==month.getMonth()?'outside-month ':''}${calendarDateKey(new Date())===key?'current-day':''}"><b>${d.getDate()}</b>${dayEvents.slice(0,3).map(event=>`<div class="month-event ${event[3]}" title="${event[1]}">${event[1]}</div>`).join('')}</div>`}).join('')}</div>`}else{const start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7)+calendarWeekOffset*7);const end=new Date(start);end.setDate(start.getDate()+6);if(title)title.textContent=`${fmt(start)} – ${fmt(end)}`;const dayNames=['จ.','อ.','พ.','พฤ.','ศ.','ส.','อา.'];wrap.innerHTML=dayNames.map((label,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const key=calendarDateKey(d);const dayEvents=data.events.filter(e=>e[0]===key);return`<div class="planner-day ${i===((new Date().getDay()+6)%7)&&calendarWeekOffset===0?'current-day':''}"><span>${label} ${d.getDate()}</span>${dayEvents.length?dayEvents.map(event=>`<div class="planner-event ${event[3]}"><b>${event[1]}</b><small>${event[2]}</small></div>`).join(''):'<div class="empty-slot">ว่าง</div>'}</div>`}).join('')}document.querySelectorAll('.planner-date>button').forEach((btn,i)=>btn.onclick=()=>{if(calendarViewMode==='month')calendarMonthOffset+=i===0?-1:1;else calendarWeekOffset+=i===0?-1:1;renderThreeCalendar(mode)});document.querySelectorAll('[data-calendar-view]').forEach(btn=>btn.onclick=()=>{calendarViewMode=btn.dataset.calendarView;renderThreeCalendar(mode)})}

// Premium interaction/accessibility layer. It observes the existing view logic
// so Classroom, Calendar, and Study Room behavior remains unchanged.
(() => {
  const views = [...document.querySelectorAll('.view')];
  const navItems = [...document.querySelectorAll('.nav-item[data-view]')];
  const syncNavigationState = () => {
    const active = document.querySelector('.view.active-view');
    const page = active?.id?.replace(/-view$/, '') || 'dashboard';
    document.body.dataset.page = page;
    navItems.forEach(item => item.setAttribute('aria-current', item.dataset.view === page ? 'page' : 'false'));
  };

  navItems.forEach(item => item.setAttribute('aria-current', item.classList.contains('active') ? 'page' : 'false'));
  views.forEach(view => view.setAttribute('aria-live', 'polite'));
  document.querySelector('#task-list')?.setAttribute('aria-live', 'polite');
  document.querySelector('#all-task-list')?.setAttribute('aria-live', 'polite');
  document.querySelector('#study-result')?.setAttribute('aria-live', 'polite');
  document.querySelector('#planner-assistant-result')?.setAttribute('aria-live', 'polite');
  document.querySelectorAll('.planner-date>button').forEach((button, index) => button.setAttribute('aria-label', index === 0 ? 'ช่วงก่อนหน้า' : 'ช่วงถัดไป'));
  document.querySelectorAll('.calendar-nav button').forEach((button, index) => button.setAttribute('aria-label', index === 0 ? 'เดือนก่อนหน้า' : 'เดือนถัดไป'));
  const labelDynamicControls = () => {
    document.querySelectorAll('.check').forEach(button => {
      const title = button.closest('.task-row')?.querySelector('.task-title')?.textContent?.trim() || 'งานนี้';
      button.setAttribute('aria-label', button.classList.contains('done') ? `ทำเครื่องหมายว่ายังไม่เสร็จ: ${title}` : `ทำเครื่องหมายว่าเสร็จแล้ว: ${title}`);
    });
    document.querySelectorAll('.switch input').forEach(input => {
      const title = input.closest('.setting-row')?.querySelector('strong')?.textContent?.trim();
      if (title) input.setAttribute('aria-label', title);
    });
  };
  labelDynamicControls();
  document.querySelectorAll('#task-list, #all-task-list').forEach(list => new MutationObserver(labelDynamicControls).observe(list, { childList: true, subtree: true }));

  document.addEventListener('click', event => {
    const trigger = event.target.closest?.('[data-view]');
    if (!trigger) return;
    const next = document.querySelector(`#${trigger.dataset.view}-view`);
    const current = document.querySelector('.view.active-view');
    if (!next || next === current) {
      syncNavigationState();
      return;
    }
    current?.classList.add('view-exit');
    window.setTimeout(() => current?.classList.remove('view-exit'), 190);
    next.classList.remove('view-enter');
    void next.offsetWidth;
    next.classList.add('view-enter');
    window.setTimeout(() => next.classList.remove('view-enter'), 380);
    window.setTimeout(syncNavigationState, 0);
  }, true);

  syncNavigationState();
})();

// Bounded shell events keep the UI layer separate from feature internals.
document.addEventListener('studyflow:sync', () => syncAllRemoteData());
document.addEventListener('studyflow:toast', event => showToast(String(event.detail || 'บันทึกแล้ว')));

async function openTaskDetail(index){const task=tasks[index],modal=document.querySelector('#task-detail-modal');if(!task||!modal)return;modal.hidden=false;document.querySelector('#task-detail-title').textContent=task.title||'รายละเอียดงาน';document.querySelector('#task-detail-due').textContent=task.deadline?`กำหนดส่ง: ${task.deadline}`:'ยังไม่กำหนดวันส่ง';document.querySelector('#task-detail-description').textContent='กำลังโหลดรายละเอียด…';document.querySelector('#task-attachments').innerHTML='';const submitBox=document.querySelector('#task-submit-box');submitBox.hidden=task.done||!task.courseId||!task.courseWorkId;try{if(!task.courseId||!task.courseWorkId){document.querySelector('#task-detail-description').textContent=task.meta||'งานนี้ถูกสร้างไว้ในเครื่อง';return}const detail=await studyApi(`/api/classroom/task-detail?courseId=${encodeURIComponent(task.courseId)}&courseWorkId=${encodeURIComponent(task.courseWorkId)}`);document.querySelector('#task-detail-description').innerHTML=escapeTaskHtml(detail.description).replace(/\n/g,'<br>')||'ครูไม่ได้ใส่รายละเอียดเพิ่มเติม';const materials=(detail.materials||[]).map(material=>{const drive=material.driveFile?.driveFile||material.driveFile;return{title:drive?.title||material.link?.title||material.youtubeVideo?.title||'ไฟล์แนบจาก Classroom',url:drive?.alternateLink||material.link?.url||material.youtubeVideo?.alternateLink||''}}).filter(x=>x.url);document.querySelector('#task-attachments').innerHTML=materials.length?`<strong>ไฟล์และสื่อประกอบ</strong>${materials.map(file=>`<button class="attachment-link" type="button" data-external-url="${escapeTaskHtml(file.url)}">↗ ${escapeTaskHtml(file.title)}</button>`).join('')}`:'<small class="muted">ไม่มีไฟล์แนบในงานนี้</small>';document.querySelector('#task-submit-button').dataset.courseId=task.courseId;document.querySelector('#task-submit-button').dataset.courseWorkId=task.courseWorkId}catch(error){document.querySelector('#task-detail-description').textContent='ไม่สามารถโหลดรายละเอียดจาก Classroom ได้ กรุณาซิงก์ใหม่แล้วลองอีกครั้ง'}}
document.addEventListener('click',event=>{const detailButton=event.target.closest?.('.task-detail-btn');if(detailButton){openTaskDetail(Number(detailButton.dataset.taskIndex));return}const attachment=event.target.closest?.('[data-external-url]');if(attachment){window.open(attachment.dataset.externalUrl,'_blank','noopener');return}if(event.target.closest?.('#task-detail-close')||event.target===document.querySelector('#task-detail-modal'))document.querySelector('#task-detail-modal').hidden=true;if(event.target.closest?.('#task-submit-button')){const button=event.target.closest('#task-submit-button'),link=document.querySelector('#task-submit-link').value.trim();if(!link){showToast('ใส่ลิงก์ไฟล์ก่อนส่งงาน');return}button.disabled=true;fetch(`/api/classroom/task-submit?courseId=${encodeURIComponent(button.dataset.courseId)}&courseWorkId=${encodeURIComponent(button.dataset.courseWorkId)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({link})}).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||'ส่งงานไม่สำเร็จ');const task=tasks.find(x=>x.courseId===button.dataset.courseId&&x.courseWorkId===button.dataset.courseWorkId);if(task)task.done=true;renderTasks();document.querySelector('#task-detail-modal').hidden=true;showToast('ส่งงานไปยัง Google Classroom แล้ว')}).catch(error=>showToast(error.message)).finally(()=>{button.disabled=false})}});

// Reasoned local scheduler: deadlines first, effort-aware blocks, protected rest, and editable overrides.
function scheduleStorage(){try{const plan=JSON.parse(localStorage.getItem('studyflow.workPlan')||'null');if(plan?.events)plan.events=plan.events.map(event=>{if(Array.isArray(event)){event.manual=Boolean(event[6]);event.taskId=event[5]}return event});return plan}catch{return null}}
function saveScheduleStorage(plan){localStorage.setItem('studyflow.workPlan',JSON.stringify(plan))}
function scheduleMinutes(task){const match=`${task.meta||''} ${task.title||''}`.match(/(\d+)\s*นาที/);if(match)return Math.max(20,Math.min(120,Number(match[1])));if(/รายงาน|โครงงาน|มายแมพ|essay|project/i.test(task.title||''))return 60;if(/แบบฝึกหัด|worksheet|โจทย์/i.test(task.title||''))return 45;return 35}
function scheduleDeadline(task,base){const value=task.deadline||'';const thai={'ม.ค.':0,'ก.พ.':1,'มี.ค.':2,'เม.ย.':3,'พ.ค.':4,'มิ.ย.':5,'ก.ค.':6,'ส.ค.':7,'ก.ย.':8,'ต.ค.':9,'พ.ย.':10,'ธ.ค.':11};if(/วันนี้/.test(value))return new Date(base);if(/พรุ่งนี้/.test(value)){const d=new Date(base);d.setDate(d.getDate()+1);return d}const match=value.match(/(\d{1,2})\s+(ม\.ค\.|ก\.พ\.|มี\.ค\.|เม\.ย\.|พ\.ค\.|มิ\.ย\.|ก\.ค\.|ส\.ค\.|ก\.ย\.|ต\.ค\.|พ\.ย\.|ธ\.ค\.)\s+(\d{4})/);if(match)return new Date(Number(match[3])-543,thai[match[2]],Number(match[1]));const d=new Date(base);d.setDate(d.getDate()+7);return d}
function scheduleRoutine(){try{return JSON.parse(localStorage.getItem('studyflow.routine')||'{}')}catch{return{}}}
function scheduleWindow(date,routine){const day=date.getDay(),weekend=day===0||day===6;let start=weekend?10*60:18*60,end=weekend?20*60:22*60;const range=(routine.text||'').match(/(\d{1,2})(?::(\d{2}))?\s*[-–ถึง]\s*(\d{1,2})(?::(\d{2}))?/);if(range&&!weekend){const blockedEnd=Number(range[3])*60+Number(range[4]||0);if(blockedEnd>start)start=Math.min(end-30,blockedEnd+30)}const saved=scheduleStorage()?.sleep||{};const sleepStart=(saved.start||'23:00').split(':').map(Number);const sleepEnd=(saved.end||'07:00').split(':').map(Number);const sleepLimit=sleepStart[0]*60+sleepStart[1];if(sleepLimit>start)end=Math.min(end,sleepLimit-30);if(end-start<25)end=start+25;return{start,end,sleepEnd:sleepEnd[0]*60+sleepEnd[1]}}
function scheduleClock(minutes){return `${String(Math.floor(minutes/60)%24).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`}
function localScheduleKey(date){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`}
function autoRescheduleWorkCalendar(reason='อัปเดตตารางงาน'){const routineInput=document.querySelector('#routine-input')?.value.trim()||scheduleRoutine().text||'';if(routineInput)localStorage.setItem('studyflow.routine',JSON.stringify({text:routineInput,updatedAt:Date.now()}));const now=new Date();now.setHours(0,0,0,0);const pending=tasks.filter(task=>!task.done);const previous=scheduleStorage()?.events||[];const manual=new Map(previous.filter(event=>event.manual&&event.taskId).map(event=>[String(event.taskId),event]));const usage={};const events=[];const ordered=[...pending].sort((a,b)=>scheduleDeadline(a,now)-scheduleDeadline(b,now));for(const task of ordered){const taskId=String(task.id||task.courseWorkId||task.title);if(manual.has(taskId)){events.push(manual.get(taskId));continue}const minutes=scheduleMinutes(task),due=scheduleDeadline(task,now),deadline=due<now?new Date(now):due;let placed=false;for(let offset=0;offset<14&&!placed;offset++){const date=new Date(now);date.setDate(now.getDate()+offset);if(date>deadline&&offset>0)break;const window=scheduleWindow(date,{text:routineInput}),used=usage[localScheduleKey(date)]||window.start;if(used+minutes>window.end||used+minutes>window.start+150)continue;const start=used+(used===window.start?0:10),end=start+minutes;const event={date:localScheduleKey(date),title:task.title,tag:task.tag||'งานจาก Classroom',className:'work-event',time:`${scheduleClock(start)}–${scheduleClock(end)}`,taskId,manual:false,reason:due<=new Date(now.getTime()+86400000*2)?'เร่งตามกำหนดส่ง':'กระจายภาระงาน'};events.push([event.date,event.title,event.tag,event.className,event.time,event.taskId,event.manual,event.reason]);usage[event.date]=end;placed=true}if(!placed){const date=new Date(deadline);const key=localScheduleKey(date);events.push([key,task.title,task.tag||'งานจาก Classroom','work-event','เวลาพิเศษ',taskId,false,'ใกล้กำหนดส่ง'])}}
calendarModes.work.events=events;saveScheduleStorage({routine:routineInput,sleep:scheduleStorage()?.sleep||{},events,updatedAt:Date.now(),reason});const active=document.querySelector('.calendar-tab.active')?.dataset.calendar||'deadline';if(active==='work')renderThreeCalendar('work');document.querySelectorAll('.calendar-tab').forEach(tab=>{if(tab.dataset.calendar==='work'){const count=events.length;tab.querySelector('span')?.replaceChildren(document.createTextNode(String(count)))}});const result=document.querySelector('#planner-assistant-result');if(result&&events.length)result.innerHTML=`<strong>จัดตารางอัตโนมัติแล้ว</strong><p>เรียงตามกำหนดส่ง ประเมินเวลาจากประเภทงาน และจำกัดภาระงานไม่เกินประมาณ 150 นาทีต่อวัน พร้อมกันเวลานอนและกิจวัตรของคุณ</p><ul>${events.slice(0,5).map(event=>`<li>${event[0]} ${event[4]} · ${event[1]}</li>`).join('')}</ul><small>คลิกบล็อกงานใน “ปฏิทินการทำงาน” เพื่อแก้เวลาเองได้ · ${reason}</small>`;return events}
function decorateWorkEvents(){if(document.querySelector('.calendar-tab.active')?.dataset.calendar!=='work')return;const events=calendarModes.work.events||[];document.querySelectorAll('#three-calendar .planner-event,#three-calendar .month-event').forEach(node=>{const title=node.querySelector('b')?.textContent||node.textContent.trim();const index=events.findIndex(event=>event[1]===title);if(index>=0){node.dataset.workIndex=String(index);node.title='คลิกเพื่อแก้เวลางาน'}})}
new MutationObserver(decorateWorkEvents).observe(document.querySelector('#three-calendar')||document.body,{childList:true,subtree:true});
document.addEventListener('click',event=>{const block=event.target.closest?.('[data-work-index]');if(!block)return;const index=Number(block.dataset.workIndex),item=calendarModes.work.events[index];if(!item)return;const nextDate=prompt('วันที่ใหม่ (YYYY-MM-DD)',item[0]);if(!nextDate)return;const nextTime=prompt('เวลาใหม่ (เช่น 18:30–19:15)',item[4]||'18:00–18:40');if(!nextTime)return;item[0]=nextDate;item[4]=nextTime;item[6]=true;const stored=scheduleStorage()||{};stored.events=calendarModes.work.events;saveScheduleStorage(stored);renderThreeCalendar('work');showToast('แก้ไขช่วงเวลางานแล้ว')});
document.addEventListener('click',event=>{if(event.target.closest?.('#generate-plan'))setTimeout(()=>autoRescheduleWorkCalendar('ปรับตามกิจวัตรล่าสุด'),80)});
let lastAutoScheduleSignature='';setInterval(()=>{const signature=tasks.filter(task=>!task.done).map(task=>`${task.id||task.title}:${task.deadline}`).join('|');if(signature!==lastAutoScheduleSignature){lastAutoScheduleSignature=signature;autoRescheduleWorkCalendar('มีงานใหม่หรือสถานะงานเปลี่ยน')}},1200);
function setupPlannerPreferenceInputs(){const routine=document.querySelector('#routine-input');if(!routine||document.querySelector('#preference-input'))return;const grid=document.createElement('div');grid.className='planner-input-grid';const routineLabel=document.createElement('label');routineLabel.className='planner-input-label';routineLabel.innerHTML='<span>กิจวัตรประจำวัน</span><small>เวลาที่ต้องถือเป็นข้อจำกัดหลัก</small>';const preferenceLabel=document.createElement('label');preferenceLabel.className='planner-input-label';preferenceLabel.innerHTML='<span>Preference / ความคิดเห็น</span><small>บอกความรู้สึกและสิ่งที่อยากให้ระบบปรับ</small>';routine.parentNode.insertBefore(grid,routine);grid.append(routineLabel,preferenceLabel);routineLabel.appendChild(routine);const preference=document.createElement('textarea');preference.id='preference-input';preference.rows=4;preference.placeholder='เช่น พักน้อยเกินไป, อย่าให้งานถมเกิน 2 งานต่อวัน, ขอมีเวลานอนอย่างน้อย 8 ชั่วโมง, วิชาคณิตใช้สมาธิมาก';preferenceLabel.appendChild(preference);const saved=scheduleRoutine();if(saved.text)routine.value=saved.text;if(saved.preference)preference.value=saved.preference;const button=document.querySelector('#generate-plan');button.onclick=()=>{const text=routine.value.trim(),pref=preference.value.trim();if(!text){showToast('ใส่กิจวัตรประจำวันก่อน แล้วฉันจะใช้เป็นข้อจำกัดหลัก');return}localStorage.setItem('studyflow.routine',JSON.stringify({text,preference:pref,updatedAt:Date.now()}));autoRescheduleWorkCalendar(pref?'ปรับตาม Preference ล่าสุด':'ปรับตามกิจวัตรล่าสุด');showToast('บันทึกข้อมูลและจัดตารางใหม่แล้ว');document.querySelector('[data-calendar="work"]')?.click()}}
setupPlannerPreferenceInputs();
const baseScheduleWindow=scheduleWindow;scheduleWindow=(date,routine)=>{const result=baseScheduleWindow(date,routine),preference=scheduleRoutine().preference||'';if(/พักน้อย|พักน้อยเกินไป|งานถม|เยอะเกิน|ไม่เกิน\s*\d+\s*งาน/i.test(preference))result.end=Math.min(result.end,result.start+90);if(/นอนน้อย|เพิ่มเวลานอน|นอนให้พอ|อย่างน้อย\s*8\s*ชั่วโมง/i.test(preference))result.end=Math.min(result.end,result.start+120);return result};
function decorateWorkTimes(){if(document.querySelector('.calendar-tab.active')?.dataset.calendar!=='work')return;(calendarModes.work.events||[]).forEach((event,index)=>{const node=document.querySelector(`#three-calendar [data-work-index="${index}"]`);const small=node?.querySelector('small');if(small&&event[4]&&!small.textContent.includes(event[4]))small.textContent=`${event[4]} · ${event[2]}`})}
new MutationObserver(decorateWorkTimes).observe(document.querySelector('#three-calendar')||document.body,{childList:true,subtree:true});

function studyTopicsFromInput(value){return String(value||'').split(/\n|;|,/).map(line=>line.trim()).filter(Boolean).map(line=>{const parts=line.split(/\s*[:：-]\s*/);return{subject:parts.length>1?parts[0].trim():'วิชาทั่วไป',topic:parts.length>1?parts.slice(1).join(':').trim():line}})}
function studyMinutes(topic){const text=`${topic.subject} ${topic.topic}`;if(/ยาก|ยากมาก|ซับซ้อน|วิเคราะห์|โครงงาน|สอบ/i.test(text))return 90;if(/กลาง|ทบทวน|แบบฝึกหัด|โจทย์/i.test(text))return 60;return 40}
function studyChatReply(message){const text=String(message||'');if(/พัก|แน่น|ชน|เยอะ/i.test(text))return'ฉันจะเว้นช่วงพักอย่างน้อย 10 นาที ลดเวลาต่อวัน และกระจายหัวข้อไปวันถัดไปเพื่อไม่ให้ตารางแน่นเกินไป';if(/นอน|ดึก/i.test(text))return'ฉันจะไม่วางช่วงติวหลังเวลานอน และกันเวลาเตรียมตัวก่อนนอนอย่างน้อย 30 นาที';if(/ยาก|ซับซ้อน/i.test(text))return'หัวข้อนี้ควรแบ่งเป็นช่วง 45–60 นาที พร้อมช่วงทบทวนสั้น ๆ ในวันถัดไป เพื่อให้จำได้นานขึ้น';return'ฉันจะใช้ข้อความนี้เป็น Preference ในการจัดตารางครั้งถัดไป โดยยังคงกำหนดส่งและเวลาพักเป็นข้อจำกัดหลัก'}
function buildStudyPlan(input,preference){const topics=studyTopicsFromInput(input),events=[],now=new Date();now.setHours(0,0,0,0);const used={};for(const topic of topics){const minutes=studyMinutes(topic);let placed=false;for(let offset=0;offset<31&&!placed;offset++){const date=new Date(now);date.setDate(now.getDate()+offset);const window=scheduleWindow(date,{text:preference||''}),key=localScheduleKey(date),start=Math.max(window.start,used[key]||window.start);if(start+minutes>window.end||start+minutes>window.start+120)continue;const end=start+minutes;const reason=minutes>=90?'หัวข้อมีความยากหรือซับซ้อน จึงแบ่งเวลาให้นานขึ้น':minutes>=60?'หัวข้อต้องใช้เวลาทบทวนและทำความเข้าใจ':'หัวข้อพื้นฐาน จัดเป็นช่วงสั้นเพื่อรักษาสมาธิ';events.push([key,`${topic.subject}: ${topic.topic}`,topic.subject,'study-event',`${scheduleClock(start)}–${scheduleClock(end)}`,'study-'+events.length,false,reason]);used[key]=end+10;placed=true}if(!placed){const date=new Date(now);date.setDate(now.getDate()+30);events.push([localScheduleKey(date),`${topic.subject}: ${topic.topic}`,topic.subject,'study-event','เวลาพิเศษ','study-'+events.length,false,'ตารางเต็ม จึงเลื่อนไปช่วงท้ายเดือน'])}}calendarModes.study.events=events;localStorage.setItem('studyflow.studyPlan',JSON.stringify({input,preference,events,updatedAt:Date.now()}));return events}
function renderPlannerModeAssistant(mode){const view=document.querySelector('.planner-assistant');const grid=document.querySelector('#three-calendar');if(!view)return;if(grid)grid.hidden=mode==='deadline';if(mode==='deadline'){const now=new Date(),pending=tasks.filter(task=>!task.done),soon=pending.filter(task=>{const due=scheduleDeadline(task,now);return due<=new Date(now.getTime()+14*86400000)}).sort((a,b)=>scheduleDeadline(a,now)-scheduleDeadline(b,now));view.innerHTML=`<div><span class="eyebrow">DEADLINE RADAR</span><h3>งานที่กำลังจะมาถึง</h3><p>สรุปเฉพาะงานที่ยังไม่เสร็จ เพื่อให้เห็นภาพรวมสัปดาห์นี้และสัปดาห์หน้าโดยไม่ต้องจัดตารางซ้ำ</p></div><div id="deadline-radar" class="planner-radar">${soon.length?soon.map(task=>{const due=scheduleDeadline(task,now),days=Math.max(0,Math.ceil((due-now)/86400000));return`<article><strong>${escapeTaskHtml(task.title)}</strong><small>${escapeTaskHtml(task.tag||'Google Classroom')} · ${days<=2?'ใกล้กำหนดส่ง':'กำหนดส่ง '+(task.deadline||'ยังไม่ระบุ')}</small><p>${days<=2?'ควรเริ่มก่อนเพื่อกันเวลาตรวจงานและลดความเร่งรีบ':'ยังมีเวลา จึงเก็บไว้เป็นลำดับถัดไปหลังงานเร่งด่วน'}</p></article>`}).join(''):'<div class="planner-empty">สัปดาห์นี้ยังไม่มีงานค้างที่ใกล้กำหนด</div>'}</div>`;return}if(mode==='study'){view.innerHTML=`<div><span class="eyebrow">STUDY ROUTER AI</span><h3>วางแผนการติวทั้งเดือน</h3><p>ใส่รูปแบบ <b>วิชา: หัวข้อ</b> แยกบรรทัด ระบบจะประเมินความซับซ้อนและกระจายช่วงติวให้เหมาะกับเวลาพัก</p></div><div class="planner-input-grid"><label class="planner-input-label"><span>วิชาและเนื้อหาที่ต้องการติว</span><small>ระบุหัวข้อของเดือนนี้</small><textarea id="study-input" rows="5" placeholder="ชีววิทยา: ระบบหายใจ (ยาก)\nคณิตศาสตร์: ความน่าจะเป็น\nภาษาอังกฤษ: Unit 3 vocabulary"></textarea></label><label class="planner-input-label"><span>Preference / ความคิดเห็น</span><small>บอกว่าตารางแน่น พักน้อย หรือตารางชนกันอย่างไร</small><textarea id="study-preference-input" rows="5" placeholder="เช่น ไม่อยากติวดึก ขอพักทุก 45 นาที และอย่าให้วันเดียวแน่นเกินไป"></textarea></label></div><div class="planner-assistant-actions"><button class="button button-primary" id="generate-study-plan">✦ จัดตารางติว</button><span class="muted">ระบบจะแสดงเหตุผลของแต่ละช่วงเวลาให้ตรวจสอบได้</span></div><div id="study-plan-result" class="planner-result"></div><div class="planner-chat"><div class="planner-chat-title">คุยกับ StudyFlow AI เรื่อง Preference</div><div id="study-preference-chat" class="planner-chat-log"><div class="planner-chat-bubble bot">บอกฉันได้เลยว่าช่วงไหนแน่นไป พักน้อย หรือตารางชนกัน ฉันจะแนะนำการปรับวันและเวลาให้</div></div><div class="planner-chat-compose"><input id="study-chat-input" placeholder="เช่น วันนี้ตารางแน่นเกินไป"><button class="button button-secondary" id="study-chat-send">ส่ง</button></div></div>`;const saved=JSON.parse(localStorage.getItem('studyflow.studyPlan')||'null');if(saved){document.querySelector('#study-input').value=saved.input||'';document.querySelector('#study-preference-input').value=saved.preference||''}return}view.innerHTML=`<div><span class="eyebrow">LIFE PLANNER AI</span><h3>เล่าเวลาในชีวิตประจำวันของคุณ</h3><p>กิจวัตรเป็นข้อจำกัดหลัก ส่วน Preference ใช้บอกความรู้สึกเพื่อปรับตารางงานให้ไม่กระทบชีวิตประจำวัน</p></div><textarea id="routine-input" rows="4" placeholder="เช่น เรียนจันทร์–ศุกร์ 08:00–16:00 นอน 23:00 และมีเวลาว่างหลัง 18:00"></textarea><div class="planner-assistant-actions"><button class="button button-primary" id="generate-plan">✦ จัดแผนให้ฉัน</button><span class="muted">แก้ไขบล็อกงานในปฏิทินได้ด้วยการคลิก</span></div><div id="planner-assistant-result" class="planner-result"></div>`;setupPlannerPreferenceInputs()}
document.addEventListener('click',event=>{const tab=event.target.closest?.('.calendar-tab');if(tab)setTimeout(()=>renderPlannerModeAssistant(tab.dataset.calendar||'deadline'),0);if(event.target.closest?.('#generate-study-plan')){const input=document.querySelector('#study-input')?.value.trim()||'',pref=document.querySelector('#study-preference-input')?.value.trim()||'';if(!input){showToast('ใส่วิชาและหัวข้อที่ต้องการติวก่อน');return}const events=buildStudyPlan(input,pref),result=document.querySelector('#study-plan-result');if(result)result.innerHTML=`<strong>จัดตารางติวแล้ว ${events.length} ช่วง</strong><p>จัดตามความยาก ความยาวของหัวข้อ เวลาพัก และเวลานอน โดยวางหัวข้อยากก่อนเพื่อให้มีเวลาทบทวนซ้ำ</p><ul>${events.slice(0,6).map(e=>`<li>${e[0]} ${e[4]} · ${escapeTaskHtml(e[1])}<small>${e[7]}</small></li>`).join('')}</ul>`;renderThreeCalendar('study');showToast('สร้างตารางติวพร้อมเหตุผลแล้ว')}if(event.target.closest?.('#study-chat-send')){const input=document.querySelector('#study-chat-input'),log=document.querySelector('#study-preference-chat');if(!input?.value.trim()||!log)return;const message=input.value.trim();log.insertAdjacentHTML('beforeend',`<div class="planner-chat-bubble user">${escapeTaskHtml(message)}</div><div class="planner-chat-bubble bot">${studyChatReply(message)}</div>`);input.value='';}});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.id==='study-chat-input'){event.preventDefault();document.querySelector('#study-chat-send')?.click()}});
setTimeout(()=>renderPlannerModeAssistant(document.querySelector('.calendar-tab.active')?.dataset.calendar||'deadline'),0);

let classroomHubWorkItems=[],classroomHubResources=[];
const classroomResourceUrl=material=>{const drive=material?.driveFile?.driveFile||material?.driveFile;return drive?.alternateLink||material?.link?.url||material?.youtubeVideo?.alternateLink||''};
function classroomDueLabel(item){if(!item?.dueDate)return'ไม่มีกำหนดส่ง';const date=new Date(item.dueDate.year,item.dueDate.month-1,item.dueDate.day);return`ส่ง ${date.toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'})}${item.dueTime?` · ${String(item.dueTime.hours||0).padStart(2,'0')}:${String(item.dueTime.minutes||0).padStart(2,'0')} น.`:''}`}
function renderClassroomHub(){const root=document.querySelector('#classroom-hub-root');if(!root)return;root.innerHTML='<div class="classroom-hub-loading"><span class="spinner"></span><strong>กำลังเปิดแผนผังห้องเรียน…</strong><small>กำลังดึงห้อง งาน และประกาศจาก Google Classroom</small></div>';studyApi('/api/classroom/courses').then(data=>{const courses=data.courses||[];document.querySelector('.classroom-badge-count')?.replaceChildren(document.createTextNode(String(courses.length)));root.innerHTML=`<div class="classroom-atlas-intro"><div><span class="eyebrow">YOUR CLASSROOM CONSTELLATION</span><h3>ห้องเรียนทั้งหมด</h3><p>เลือกห้องเพื่อดูงานและประกาศในมุมมองแบบแผนผัง ไม่ต้องสลับไป Google Classroom</p></div><span class="classroom-source-pill">${data.source==='google-classroom'?'● เชื่อมต่อ Google Classroom':'โหมดรอการเชื่อมต่อ'}</span></div><div class="classroom-course-grid">${courses.length?courses.map((course,index)=>`<button class="classroom-course-card" type="button" data-classroom-course-index="${index}"><span class="course-orbit-number">${String(index+1).padStart(2,'0')}</span><span class="course-card-main"><strong>${escapeTaskHtml(course.name)}</strong><small>${escapeTaskHtml(course.section||course.room||'Google Classroom')}</small><em>${escapeTaskHtml(course.description||'เปิดแผนผังงานและประกาศของห้องนี้')}</em></span><span class="course-card-arrow">↗</span></button>`).join(''):'<div class="classroom-empty"><strong>ยังไม่พบห้องเรียน</strong><span>ตรวจสอบการเชื่อมต่อ Google Classroom แล้วลองกด Sync ใหม่</span></div>'}</div>`;window.studyflowClassroomCourses=courses}).catch(error=>{root.innerHTML=`<div class="classroom-empty"><strong>โหลดห้องเรียนไม่สำเร็จ</strong><span>${escapeTaskHtml(error.message||'กรุณาเชื่อมต่อ Google Classroom ก่อน')}</span><button class="primary-btn" type="button" data-view="settings">ไปที่ตั้งค่า</button></div>`})}
function renderClassroomCourse(index){const root=document.querySelector('#classroom-hub-root'),course=window.studyflowClassroomCourses?.[index];if(!root||!course)return;root.innerHTML='<div class="classroom-hub-loading"><span class="spinner"></span><strong>กำลังจัดวางแผนผังห้องเรียน…</strong><small>กำลังโหลดงาน ประกาศ และไฟล์ประกอบ</small></div>';studyApi(`/api/classroom/course?courseId=${encodeURIComponent(course.id)}`).then(data=>{classroomHubWorkItems=data.coursework||[];classroomHubResources=[];const announcements=data.announcements||[],topics=data.topics||[];root.innerHTML=`<div class="classroom-course-toolbar"><button class="button button-secondary" type="button" data-classroom-back>← ห้องเรียนทั้งหมด</button><span class="classroom-source-pill">${escapeTaskHtml(data.course.name)}</span>${data.course.alternateLink?`<button class="link-btn" type="button" data-classroom-url="${escapeTaskHtml(data.course.alternateLink)}">เปิดห้องต้นฉบับ ↗</button>`:''}</div><div class="classroom-course-hero"><div><span class="eyebrow">ACTIVE CLASSROOM</span><h3>${escapeTaskHtml(data.course.name)}</h3><p>${escapeTaskHtml(data.course.description||data.course.section||'แผนผังการเรียนรู้ของห้องนี้')}</p></div><div class="course-hero-stat"><b>${classroomHubWorkItems.length}</b><small>งานที่เผยแพร่</small></div><div class="course-hero-stat"><b>${announcements.length}</b><small>ประกาศ</small></div></div><div class="classroom-content-layout"><section class="classroom-stream"><div class="classroom-section-heading"><div><span class="eyebrow">WORKSTREAM</span><h4>งานและไฟล์</h4></div><span>${classroomHubWorkItems.length} รายการ</span></div>${classroomHubWorkItems.length?classroomHubWorkItems.map((item,itemIndex)=>{const materials=(item.materials||[]).map(material=>{const url=classroomResourceUrl(material);const resourceIndex=classroomHubResources.push({url,title:material.driveFile?.driveFile?.title||material.link?.title||material.youtubeVideo?.title||'ไฟล์แนบ'})-1;return url?`<button class="classroom-resource-chip" type="button" data-classroom-resource-index="${resourceIndex}">↗ ${escapeTaskHtml(classroomHubResources[resourceIndex].title)}</button>`:''}).join('');return`<article class="classroom-work-card ${item.submitted?'is-submitted':''}"><div class="work-card-rail"><span>${String(itemIndex+1).padStart(2,'0')}</span><i></i></div><div class="work-card-body"><div class="work-card-top"><span class="classroom-status ${item.submitted?'submitted':'pending'}">${item.submitted?'✓ ส่งแล้ว':'● รอส่ง'}</span><small>${escapeTaskHtml(classroomDueLabel(item))}</small></div><h5>${escapeTaskHtml(item.title)}</h5><p>${escapeTaskHtml(item.description||'ครูไม่ได้ใส่รายละเอียดเพิ่มเติม')}</p><div class="classroom-card-actions"><button class="button button-primary" type="button" data-classroom-work-index="${itemIndex}">เปิดรายละเอียด</button>${item.alternateLink?`<button class="button button-secondary" type="button" data-classroom-url="${escapeTaskHtml(item.alternateLink)}">เปิดกระทู้/ความคิดเห็น ↗</button>`:''}</div>${materials?`<div class="classroom-resource-row">${materials}</div>`:''}</div></article>`}).join(''):'<div class="classroom-empty">ห้องนี้ยังไม่มีงานที่เผยแพร่</div>'}</section><aside class="classroom-side-rail"><section class="classroom-panel"><div class="classroom-section-heading"><div><span class="eyebrow">STREAM NOTES</span><h4>ประกาศจากครู</h4></div></div>${announcements.length?announcements.slice(0,8).map(item=>`<article class="classroom-announcement"><small>${item.creationTime?new Date(item.creationTime).toLocaleDateString('th-TH'):''}</small><p>${escapeTaskHtml(item.text||'ประกาศจากครู')}</p>${item.alternateLink?`<button class="link-btn" type="button" data-classroom-url="${escapeTaskHtml(item.alternateLink)}">อ่านกระทู้ ↗</button>`:''}</article>`).join(''):'<p class="muted">ยังไม่มีประกาศใหม่</p>'}</section><section class="classroom-panel"><div class="classroom-section-heading"><div><span class="eyebrow">TOPIC MAP</span><h4>หัวข้อในห้อง</h4></div></div><div class="classroom-topic-map">${topics.length?topics.map(topic=>`<span>${escapeTaskHtml(topic.name)}</span>`).join(''):'<small class="muted">ยังไม่มีการจัดหมวดหัวข้อ</small>'}</div></section><section class="classroom-panel classroom-comments-note"><span class="eyebrow">DISCUSSION BRIDGE</span><p>${escapeTaskHtml(data.commentsNotice||'เปิดความคิดเห็นผ่านกระทู้ของ Classroom')}</p><small>ระบบจะเปิดกระทู้ในหน้าต่างของ StudyFlow เพื่อรักษาการล็อกอิน Google ของคุณ</small></section></aside></div>`}).catch(error=>{root.innerHTML=`<div class="classroom-empty"><strong>เปิดห้องเรียนไม่สำเร็จ</strong><span>${escapeTaskHtml(error.message||'ลองซิงก์ใหม่อีกครั้ง')}</span><button class="button button-secondary" type="button" data-classroom-back>← กลับไปห้องเรียน</button></div>`})}
function openClassroomHubWork(index){const item=classroomHubWorkItems[index];if(!item)return;const taskIndex=tasks.push({id:item.courseWorkId,title:item.title,meta:`${window.studyflowClassroomCourses?.find(x=>x.id===item.courseId)?.name||'Google Classroom'} · Classroom`,tag:'Google Classroom',type:'bio-tag',deadline:classroomDueLabel(item),done:item.submitted,courseId:item.courseId,courseWorkId:item.courseWorkId,link:item.alternateLink})-1;openTaskDetail(taskIndex)}
document.addEventListener('click',event=>{const courseCard=event.target.closest?.('[data-classroom-course-index]');if(courseCard){renderClassroomCourse(Number(courseCard.dataset.classroomCourseIndex));return}if(event.target.closest?.('[data-classroom-back]')){renderClassroomHub();return}const work=event.target.closest?.('[data-classroom-work-index]');if(work){openClassroomHubWork(Number(work.dataset.classroomWorkIndex));return}const resource=event.target.closest?.('[data-classroom-resource-index]');if(resource){const item=classroomHubResources[Number(resource.dataset.classroomResourceIndex)];if(item?.url)window.open(item.url,'_blank','noopener');return}const external=event.target.closest?.('[data-classroom-url]');if(external){window.open(external.dataset.classroomUrl,'_blank','noopener');return}});
document.querySelectorAll('[data-view="classroom"]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#page-title').innerHTML='ศูนย์ห้องเรียน';renderClassroomHub()}));
const classroomFileToDataUrl=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});
document.addEventListener('click',async event=>{const button=event.target.closest?.('#task-submit-button');if(!button)return;event.stopImmediatePropagation();const file=document.querySelector('#task-submit-file')?.files?.[0],link=document.querySelector('#task-submit-link')?.value.trim()||'';if(!file&&!link){showToast('เลือกไฟล์หรือใส่ลิงก์ก่อนส่งงาน');return}if(file&&file.size>20*1024*1024){showToast('ไฟล์ต้องมีขนาดไม่เกิน 20 MB');return}button.disabled=true;try{let response;if(file){const data=await classroomFileToDataUrl(file);response=await fetch(`/api/classroom/task-submit-file?courseId=${encodeURIComponent(button.dataset.courseId)}&courseWorkId=${encodeURIComponent(button.dataset.courseWorkId)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file:{name:file.name,mimeType:file.type,data}})})}else response=await fetch(`/api/classroom/task-submit?courseId=${encodeURIComponent(button.dataset.courseId)}&courseWorkId=${encodeURIComponent(button.dataset.courseWorkId)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({link})});const data=await response.json();if(!response.ok)throw new Error(data.error||'ส่งงานไม่สำเร็จ');const task=tasks.find(x=>x.courseId===button.dataset.courseId&&x.courseWorkId===button.dataset.courseWorkId);if(task)task.done=true;renderTasks();document.querySelector('#task-detail-modal').hidden=true;showToast('ส่งงานไปยัง Google Classroom แล้ว')}catch(error){showToast(error.message)}finally{button.disabled=false}},true);
function removeClassroomNavigationEscapes(){document.querySelectorAll('#classroom-hub-root [data-classroom-url]').forEach(button=>{if(/กระทู้|ห้องต้นฉบับ/.test(button.textContent||'')){const note=document.createElement('span');note.className='classroom-native-note';note.textContent='รายละเอียดและไฟล์เปิดจาก StudyFlow ได้โดยตรง';button.replaceWith(note)}})}
new MutationObserver(removeClassroomNavigationEscapes).observe(document.querySelector('#classroom-hub-root')||document.body,{childList:true,subtree:true});
function normalizeDiscussionNote(){const note=document.querySelector('.classroom-comments-note small');if(note)note.textContent='เนื้อหา ไฟล์ และการส่งงานทำใน StudyFlow ได้โดยตรง ส่วนความคิดเห็น Classroom ยังไม่มี API สำหรับฝังแบบ native'}
new MutationObserver(normalizeDiscussionNote).observe(document.querySelector('#classroom-hub-root')||document.body,{childList:true,subtree:true});
function normalizeClassroomUnknownStatus(){document.querySelectorAll('.classroom-work-card').forEach((card,index)=>{const item=classroomHubWorkItems[index];if(item?.submitted===null){const status=card.querySelector('.classroom-status');if(status){status.className='classroom-status unknown';status.textContent='○ ตรวจเมื่อเปิดรายละเอียด'}}})}
new MutationObserver(normalizeClassroomUnknownStatus).observe(document.querySelector('#classroom-hub-root')||document.body,{childList:true,subtree:true});

// Compatibility mode: open the native Classroom page inside StudyFlow's child
// window. This keeps the familiar Classroom workflow available while the Atlas
// remains the place to browse courses.
document.addEventListener('click', event => {
  const card = event.target.closest?.('[data-classroom-course-index]');
  if (!card) return;
  const course = window.studyflowClassroomCourses?.[Number(card.dataset.classroomCourseIndex)];
  if (!course?.alternateLink) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  window.open(course.alternateLink, '_blank', 'noopener');
}, true);

function openTaskInStudyFlow(task) {
  if (!task) return;
  const url = task.link || (task.courseId && task.courseWorkId
    ? `https://classroom.google.com/c/${encodeURIComponent(task.courseId)}/a/${encodeURIComponent(task.courseWorkId)}/details`
    : '');
  if (!url) { showToast('งานนี้ยังไม่มีลิงก์ Classroom'); return; }
  window.open(url, '_blank', 'noopener');
}

// Focus actions now land on the work calendar so the next step is immediately visible.
const focusButton = document.querySelector('#start-focus');
if (focusButton) focusButton.onclick = () => {
  document.querySelector('.nav-item[data-view="calendar"]')?.click();
  window.setTimeout(() => document.querySelector('[data-calendar="work"]')?.click(), 40);
  showToast('เปิดปฏิทินการทำงานแล้ว');
};

// Clicking a task row opens its Classroom assignment in the StudyFlow window.
document.addEventListener('click', event => {
  const row = event.target.closest?.('.task-row');
  if (!row || event.target.closest?.('button, a, input, select, textarea')) return;
  const title = row.querySelector('.task-title')?.textContent?.trim();
  const task = tasks.find(item => String(item.title || '').trim() === title);
  if (task) openTaskInStudyFlow(task);
});
new MutationObserver(() => {
  document.querySelectorAll('.task-row').forEach(row => {
    const title = row.querySelector('.task-title')?.textContent?.trim();
    const task = tasks.find(item => String(item.title || '').trim() === title);
    const clickable = Boolean(task?.link || (task?.courseId && task?.courseWorkId));
    row.classList.toggle('is-classroom-task', clickable);
    if (clickable) { row.setAttribute('tabindex', '0'); row.title = 'เปิดงานนี้ใน Google Classroom ผ่าน StudyFlow'; }
    else { row.removeAttribute('tabindex'); row.removeAttribute('title'); }
  });
}).observe(document.querySelector('#task-list')?.parentElement || document.body, { childList: true, subtree: true });

// StudyFlow interactive practice layer. The API still returns a readable,
// auditable text format; the client turns that format into real practice UI.
const studyflowBaseUploadStudyFileWithProgress = uploadStudyFileWithProgress;
uploadStudyFileWithProgress = payload => {
  if (payload?.action === 'summary') {
    const preference = document.querySelector('#study-summary-preference')?.value?.trim() || '';
    return studyflowBaseUploadStudyFileWithProgress({ ...payload, studySettings: { ...(payload.studySettings || {}), preference } });
  }
  return studyflowBaseUploadStudyFileWithProgress(payload);
};

function studyChoiceIndex(letter) { return { 'ก': 0, 'ข': 1, 'ค': 2, 'ง': 3 }[String(letter || '').trim()] ?? -1; }
function parseStudyQuiz(content) {
  const raw = String(content || '').replace(/\r/g, '').trim();
  const blocks = raw.split(/\n(?=\s*(?:ข้อ\s*)?\d+[.)])/i).map(x => x.trim()).filter(Boolean);
  return blocks.map((block, index) => {
    const lines = block.split('\n').map(x => x.trim()).filter(Boolean);
    if (!lines.length) return null;
    const first = lines.shift().replace(/^(?:ข้อ\s*)?\d+[.)]?\s*/i, '').trim();
    const choices = [];
    let answerLine = '', reasonLine = '', evidenceLine = '';
    lines.forEach(line => {
      const choice = line.match(/^([กขคง])\s*[.)]\s*(.+)$/);
      if (choice) choices.push({ letter: choice[1], text: choice[2].trim() });
      else if (/^เฉลย\s*:/i.test(line)) answerLine = line;
      else if (/^(?:เหตุผล|คำอธิบาย)\s*:/i.test(line)) reasonLine = line.replace(/^(?:เหตุผล|คำอธิบาย)\s*:\s*/i, '').trim();
      else if (/^แหล่งอ้างอิง\s*:/i.test(line)) evidenceLine = line.replace(/^แหล่งอ้างอิง\s*:\s*/i, '').trim();
    });
    const answer = answerLine.match(/^เฉลย\s*:\s*([กขคง])?\s*[.)]?\s*(.*)$/i);
    let answerIndex = answer ? studyChoiceIndex(answer[1]) : -1;
    if (answerIndex < 0 && answer?.[2]) answerIndex = choices.findIndex(choice => answer[2].includes(choice.text));
    return first && choices.length === 4 && answerIndex >= 0 ? { number: index + 1, question: first, choices, answerIndex, reason: reasonLine || 'เหตุผลอ้างอิงจากเนื้อหาที่อ่านได้', evidence: evidenceLine || 'ไม่พบหลักฐานอ้างอิงในผลลัพธ์' } : null;
  }).filter(Boolean);
}
function parseStudyFlashcards(content) {
  const raw = String(content || '').replace(/\r/g, '').trim();
  const blocks = raw.split(/(?=(?:แฟลชการ์ด\s*(?:ที่\s*)?\d+|flashcard\s*\d+))/i).map(x => x.trim()).filter(Boolean);
  return blocks.map((block, index) => {
    const front = block.match(/(?:ด้านหน้า|front)(?:\s*\([^)]*\))?\s*:\s*([\s\S]*?)(?=\n\s*(?:ด้านหลัง|back)(?:\s*\([^)]*\))?\s*:|$)/i)?.[1]?.trim();
    const back = block.match(/(?:ด้านหลัง|back)(?:\s*\([^)]*\))?\s*:\s*([\s\S]*?)(?=\n\s*(?:เหตุผล|คำอธิบาย)(?:\/คำอธิบาย)?\s*:|$)/i)?.[1]?.trim();
    const reason = block.match(/(?:เหตุผล\/คำอธิบาย|เหตุผล|คำอธิบาย)\s*:\s*([\s\S]*?)(?=\n\s*แหล่งอ้างอิง\s*:|$)/i)?.[1]?.trim() || 'คำอธิบายอ้างอิงจากเนื้อหาที่อ่านได้';
    const evidence = block.match(/แหล่งอ้างอิง\s*:\s*([\s\S]*)$/i)?.[1]?.trim() || 'ไม่พบหลักฐานอ้างอิงในผลลัพธ์';
    return front && back ? { number: index + 1, front, back, reason, evidence } : null;
  }).filter(Boolean);
}
function studyInteractiveHeader(data, actionLabel) {
  const source = data.source === 'qwen' ? 'Qwen 3.7 Plus' : data.source === 'deepseek' ? 'DeepSeek V4 Flash' : data.source === 'ollama-local' ? 'Qwen/Ollama ในเครื่อง' : data.source || 'StudyFlow';
  const requested = Number(data.requestedCount || 0), validated = Number(data.validatedCount || 0);
  const validationNotice = data.partialResult && requested > 0 && validated > 0
    ? `<div class="study-validation-notice" role="status"><b>แสดง ${validated} จาก ${requested} รายการที่ผ่านการตรวจหลักฐาน</b><span>รายการที่เหลือถูกตัดออก เพราะรูปแบบ ระดับความยาก หรือข้อความอ้างอิงไม่ตรงกับเอกสาร</span></div>`
    : '';
  return `<div class="result-header"><div><span class="eyebrow">AI STUDY GUIDE · ${actionLabel}</span></div><div class="result-header-actions"><span class="source-pill">${escapeTaskHtml(source)}</span><button class="study-action pdf-action" id="download-study-pdf" type="button">⇩ ดาวน์โหลด PDF</button></div></div><h3>${escapeTaskHtml(data.title || 'ผลลัพธ์การติว')}</h3>${validationNotice}`;
}
function renderQuizQuestion() {
  const state = window.studyflowQuizState, result = document.querySelector('#study-result');
  if (!state || !result) return;
  const item = state.items[state.index], selected = state.answers[state.index];
  const choices = item.choices.map((choice, index) => {
    const selectedClass = selected === index ? ' is-selected' : '';
    const statusClass = selected !== undefined ? (index === item.answerIndex ? ' is-correct' : selected === index ? ' is-wrong' : '') : '';
    return `<button type="button" class="quiz-choice${selectedClass}${statusClass}" data-quiz-choice="${index}" ${selected !== undefined ? 'disabled' : ''}><b>${choice.letter}</b><span>${escapeTaskHtml(choice.text)}</span></button>`;
  }).join('');
  const feedback = selected === undefined ? '' : `<div class="quiz-feedback ${selected === item.answerIndex ? 'is-correct' : 'is-wrong'}"><strong>${selected === item.answerIndex ? 'ถูกต้อง' : `ยังไม่ถูก — คำตอบคือ ${item.choices[item.answerIndex].letter}`}</strong><p>${escapeTaskHtml(item.reason)}</p><small class="study-evidence"><b>แหล่งอ้างอิง:</b> ${escapeTaskHtml(item.evidence)}</small></div>`;
  const next = selected === undefined ? '' : `<button type="button" class="study-action primary" data-quiz-next>${state.index === state.items.length - 1 ? 'ดูผลลัพธ์' : 'ข้อต่อไป'} →</button>`;
  result.innerHTML = `${studyInteractiveHeader(state.data, 'ข้อสอบแบบโต้ตอบ')}<div class="study-interactive quiz-interactive"><div class="quiz-progress"><span>ข้อ ${state.index + 1} / ${state.items.length}</span><i><em style="width:${((state.index + 1) / state.items.length) * 100}%"></em></i></div><article class="quiz-question"><h4>${escapeTaskHtml(item.question)}</h4><div class="quiz-choices">${choices}</div>${feedback}<div class="quiz-nav">${next}</div></article><div class="result-footer">${escapeTaskHtml(state.footer || 'อ้างอิงจากเนื้อหาที่อ่านได้')}</div></div>`;
  result.querySelector('#download-study-pdf')?.addEventListener('click', downloadStudyPdf);
}
function recordQuizStudyInsight(topics) {
  const unique = [...new Set((topics || []).map(topic => String(topic || '').replace(/\s+/g, ' ').trim()).filter(Boolean))].slice(0, 4);
  if (!unique.length) return;
  let saved = {};
  try { saved = JSON.parse(localStorage.getItem('studyflow.quizInsights') || '{}') || {}; } catch {}
  const counts = { ...(saved.counts || {}) };
  unique.forEach(topic => { counts[topic] = Number(counts[topic] || 0) + 1; });
  localStorage.setItem('studyflow.quizInsights', JSON.stringify({ counts, updatedAt: Date.now() }));
  let metrics = {};
  try { metrics = JSON.parse(localStorage.getItem('studyflow.planMetrics') || '{}') || {}; } catch {}
  metrics.reviewBlocks = Number(metrics.reviewBlocks || 0) + unique.length;
  metrics.lastUpdated = Date.now();
  localStorage.setItem('studyflow.planMetrics', JSON.stringify(metrics));
  const events = Array.isArray(calendarModes.study?.events) ? calendarModes.study.events.slice() : [];
  unique.forEach((topic, index) => {
    const date = new Date();
    date.setDate(date.getDate() + index + 1);
    const key = typeof localScheduleKey === 'function' ? localScheduleKey(date) : date.toISOString().slice(0, 10);
    const title = `ทบทวนจากผลสอบ: ${topic.slice(0, 64)}`;
    if (!events.some(event => String(event[1] || '') === title)) events.push([key, title, 'จุดที่ควรทบทวน', 'study-event', '25 นาที', `quiz-review-${Date.now()}-${index}`, false, 'ตอบผิดจากผลสอบ จึงเพิ่มเวลา 25 นาทีเพื่อทบทวนหัวข้อนี้']);
  });
  calendarModes.study.events = events;
  if (typeof renderPlannerImpactMetrics === 'function') renderPlannerImpactMetrics();
  if (typeof renderThreeCalendar === 'function' && document.querySelector('#three-calendar')) renderThreeCalendar('study');
}
